  1	// Thin fetch wrapper. Every request except /api/actors carries X-Actor-Token.
  2	
  3	export class ApiError extends Error {
  4	  constructor(status, code, message) {
  5	    super(message);
  6	    this.status = status;
  7	    this.code = code;
  8	  }
  9	}
