  4	const SORTS = [
  5	  ["issued_date", "Issued"],
  6	  ["learner_name", "Learner"],
  7	  ["course_title", "Course"],
  8	  ["serial", "Serial"],
  9	  ["status", "Status"],
 10	];
 11	const PAGE_SIZE = 20;
 12	const TOKEN_KEY = "actorToken";
 13	
 14	function readStoredToken() {
 15	  try {
 16	    return localStorage.getItem(TOKEN_KEY);
 17	  } catch {
 18	    return null;
 19	  }
 20	}
 21	
 22	function storeToken(token) {
 23	  try {
 24	    localStorage.setItem(TOKEN_KEY, token);
 25	  } catch {
 26	    // storage unavailable; the picker still works for this page load
 27	  }
 28	}
