 30	function ErrorBox({ error, onRetry }) {
 31	  if (!error) return null;
 32	  return (
 33	    <div className="error" role="alert">
 34	      {error.message}
 35	      {onRetry && (
 36	        <button type="button" onClick={onRetry}>
 37	          Retry
 38	        </button>
 39	      )}
 40	    </div>
 41	  );
 42	}
