 44	export default function App() {
 45	  const [actors, setActors] = useState(null);
 46	  const [actorsError, setActorsError] = useState(null);
 47	  const [token, setToken] = useState(readStoredToken);
 48	  const [me, setMe] = useState(null);
 49	  const [view, setView] = useState("list");
 50	  const [selectedId, setSelectedId] = useState(null);
 51	
 52	  const loadActors = useCallback(() => {
 53	    setActorsError(null);
 54	    api
 55	      .actors()
 56	      .then((list) => {
 57	        setActors(list);
 58	        setToken((t) => (list.some((a) => a.token === t) ? t : list[0]?.token ?? null));
 59	      })
 60	      .catch(setActorsError);
 61	  }, []);
 62	  useEffect(loadActors, [loadActors]);
 63	
 64	  useEffect(() => {
 65	    setMe(null);
 66	    setSelectedId(null);
 67	    if (!token) return;
 68	    storeToken(token);
 69	    api.me(token).then(setMe, () => setMe(null));
 70	  }, [token]);
 71	
 72	  if (actorsError) return <ErrorBox error={actorsError} onRetry={loadActors} />;
 73	  if (!actors) return <p className="muted">Loading…</p>;
 74	
 75	  return (
 76	    <div className="app">
 77	      <header>
 78	        <h1>Certificates</h1>
 79	        <label>
 80	          Acting as{" "}
 81	          <select value={token ?? ""} onChange={(e) => setToken(e.target.value)}>
 82	            {actors.map((a) => (
 83	              <option key={a.token} value={a.token}>
 84	                {a.email} ({a.tenant_name})
 85	              </option>
 86	            ))}
 87	          </select>
 88	        </label>
 89	        {me && (
 90	          <span className="muted">
 91	            {me.tenant_name} · times shown in {me.timezone}
 92	          </span>
 93	        )}
 94	      </header>
 95	      <nav>
 96	        <button type="button" className={view === "list" ? "active" : ""} onClick={() => setView("list")}>
 97	          Certificates
 98	        </button>
 99	        <button type="button" className={view === "bulk" ? "active" : ""} onClick={() => setView("bulk")}>
100	          Bulk issue
101	        </button>
102	      </nav>
103	      {/* key=token: switching actor discards every per-tenant state and in-flight key */}
104	      {token && view === "list" && (
105	        <main key={token}>
106	          <CertificateList token={token} selectedId={selectedId} onSelect={setSelectedId} />
107	          {selectedId && (
108	            <CertificateDetail token={token} id={selectedId} onClose={() => setSelectedId(null)} />
109	          )}
110	        </main>
111	      )}
112	      {token && view === "bulk" && (
113	        <main key={token}>
114	          <BulkIssue token={token} />
115	        </main>
116	      )}
117	    </div>
118	  );
119	}
