121	function CertificateList({ token, selectedId, onSelect }) {
122	  const [qInput, setQInput] = useState("");
123	  const [q, setQ] = useState("");
124	  const [sort, setSort] = useState("issued_date");
125	  const [dir, setDir] = useState("desc");
126	  const [page, setPage] = useState(1);
127	  const [data, setData] = useState(null);
128	  const [loading, setLoading] = useState(true);
129	  const [error, setError] = useState(null);
130	  const [reloadTick, setReloadTick] = useState(0);
131	  const [exporting, setExporting] = useState(false);
132	  const [exportError, setExportError] = useState(null);
133	
134	  // Debounce typing into the applied query; a new query restarts at page 1.
135	  useEffect(() => {
136	    const t = setTimeout(() => {
137	      setQ(qInput.trim());
138	      setPage(1);
139	    }, 250);
140	    return () => clearTimeout(t);
141	  }, [qInput]);
142	
143	  useEffect(() => {
144	    const ctrl = new AbortController();
145	    setLoading(true);
146	    setError(null);
147	    const params = { sort, dir, page, page_size: PAGE_SIZE };
148	    if (q) params.q = q;
149	    api
150	      .listCertificates(token, params, ctrl.signal)
151	      .then((d) => {
152	        setData(d);
153	        setLoading(false);
154	      })
155	      .catch((e) => {
156	        if (e.name === "AbortError") return;
157	        setError(e);
158	        setLoading(false);
159	      });
160	    return () => ctrl.abort();
161	  }, [token, q, sort, dir, page, reloadTick]);
162	
163	  // Reload when a revoke elsewhere changes a row.
164	  useEffect(() => {
165	    const onChange = () => setReloadTick((n) => n + 1);
166	    window.addEventListener("certificate-changed", onChange);
167	    return () => window.removeEventListener("certificate-changed", onChange);
168	  }, []);
169	
170	  function clickSort(key) {
171	    if (key === sort) setDir((d) => (d === "asc" ? "desc" : "asc"));
172	    else {
173	      setSort(key);
174	      setDir(key === "issued_date" ? "desc" : "asc");
175	    }
176	    setPage(1);
177	  }
178	
179	  async function doExport() {
180	    setExporting(true);
181	    setExportError(null);
182	    try {
183	      // Same applied q/sort/dir as the rows on screen.
184	      await api.exportCsv(token, { q, sort, dir });
185	    } catch (e) {
186	      setExportError(e);
187	    } finally {
188	      setExporting(false);
189	    }
190	  }
191	
192	  const totalPages = data ? Math.max(1, Math.ceil(data.total / data.page_size)) : 1;
193	
194	  return (
195	    <section>
196	      <div className="toolbar">
197	        <input
198	          type="search"
199	          placeholder="Search learner name or serial…"
200	          value={qInput}
201	          onChange={(e) => setQInput(e.target.value)}
202	        />
203	        <button type="button" onClick={doExport} disabled={exporting}>
204	          {exporting ? "Exporting…" : "Export CSV"}
205	        </button>
206	      </div>
207	      <ErrorBox error={exportError} />
208	      <table>
209	        <thead>
210	          <tr>
211	            {SORTS.map(([key, label]) => (
212	              <th key={key}>
213	                <button type="button" className="sort" onClick={() => clickSort(key)}>
214	                  {label}
215	                  {sort === key ? (dir === "asc" ? " ▲" : " ▼") : ""}
216	                </button>
217	              </th>
218	            ))}
219	          </tr>
220	        </thead>
221	        <tbody>
222	          {data?.items.map((c) => (
223	            <tr
224	              key={c.id}
225	              className={c.id === selectedId ? "selected" : ""}
226	              onClick={() => onSelect(c.id)}
227	            >
228	              {/* Stored tenant-local values, never re-formatted in the browser's zone (A5). */}
229	              <td>{c.issued_local_time}</td>
230	              <td>{c.learner_name}</td>
231	              <td>{c.course_title}</td>
232	              <td className="mono">{c.serial}</td>
233	              <td>
234	                <span className={`badge ${c.status}`}>{c.status}</span>
235	              </td>
236	            </tr>
237	          ))}
238	        </tbody>
239	      </table>
240	      {loading && <p className="muted">Loading…</p>}
241	      <ErrorBox error={error} onRetry={() => setReloadTick((n) => n + 1)} />
242	      {!loading && !error && data?.items.length === 0 && (
243	        <p className="muted">{q ? `No certificates match "${q}".` : "No certificates yet."}</p>
244	      )}
245	      {data && data.total > 0 && (
246	        <div className="pager">
247	          <button type="button" disabled={page <= 1 || loading} onClick={() => setPage((p) => p - 1)}>
248	            Previous
249	          </button>
250	          <span>
251	            Page {data.page} of {totalPages} · {data.total} certificates
252	          </span>
253	          <button
254	            type="button"
255	            disabled={page >= totalPages || loading}
256	            onClick={() => setPage((p) => p + 1)}
257	          >
258	            Next
259	          </button>
260	        </div>
261	      )}
262	    </section>
263	  );
264	}
