266	function CertificateDetail({ token, id, onClose }) {
267	  const [cert, setCert] = useState(null);
268	  const [error, setError] = useState(null);
269	  const [confirming, setConfirming] = useState(false);
270	  const [revoking, setRevoking] = useState(false);
271	  const [revokeError, setRevokeError] = useState(null);
272	
273	  useEffect(() => {
274	    let live = true;
275	    setCert(null);
276	    setError(null);
277	    setConfirming(false);
278	    setRevokeError(null);
279	    api.certificate(token, id).then(
280	      (c) => live && setCert(c),
281	      (e) => live && setError(e),
282	    );
283	    return () => {
284	      live = false;
285	    };
286	  }, [token, id]);
287	
288	  async function revoke() {
289	    setRevoking(true);
290	    setRevokeError(null);
291	    try {
292	      setCert(await api.revoke(token, id));
293	      setConfirming(false);
294	      window.dispatchEvent(new Event("certificate-changed"));
295	    } catch (e) {
296	      setRevokeError(e);
297	    } finally {
298	      setRevoking(false);
299	    }
300	  }
301	
302	  return (
303	    <aside className="detail">
304	      <button type="button" className="close" onClick={onClose} aria-label="Close">
305	        ×
306	      </button>
307	      {!cert && !error && <p className="muted">Loading…</p>}
308	      <ErrorBox error={error} />
309	      {cert && (
310	        <>
311	          <h2 className="mono">{cert.serial}</h2>
312	          <dl>
313	            <dt>Learner</dt>
314	            <dd>{cert.learner_name}</dd>
315	            <dt>Course</dt>
316	            <dd>{cert.course_title}</dd>
317	            <dt>Status</dt>
318	            <dd>
319	              <span className={`badge ${cert.status}`}>{cert.status}</span>
320	            </dd>
321	            <dt>Issued (tenant time)</dt>
322	            <dd>{cert.issued_local_time}</dd>
323	            <dt>Issued (UTC)</dt>
324	            <dd className="mono">{cert.issued_at_utc}</dd>
325	            {cert.revoked_at_utc && (
326	              <>
327	                <dt>Revoked (UTC)</dt>
328	                <dd className="mono">{cert.revoked_at_utc}</dd>
329	              </>
330	            )}
331	          </dl>
332	          {cert.status === "active" && !confirming && (
333	            <button type="button" className="danger" onClick={() => setConfirming(true)}>
334	              Revoke…
335	            </button>
336	          )}
337	          {confirming && (
338	            <div className="confirm">
339	              <p>
340	                Revoke <strong>{cert.serial}</strong> for {cert.learner_name}? This cannot be undone.
341	              </p>
342	              <button type="button" className="danger" onClick={revoke} disabled={revoking}>
343	                {revoking ? "Revoking…" : "Confirm revoke"}
344	              </button>
345	              <button type="button" onClick={() => setConfirming(false)} disabled={revoking}>
346	                Cancel
347	              </button>
348	            </div>
349	          )}
350	          <ErrorBox error={revokeError} />
351	        </>
352	      )}
353	    </aside>
354	  );
355	}
