357	function BulkIssue({ token }) {
358	  const [courses, setCourses] = useState(null);
359	  const [coursesError, setCoursesError] = useState(null);
360	  const [courseId, setCourseId] = useState("");
361	  const [confirming, setConfirming] = useState(false);
362	  // { courseId, key } for the confirmed submission; kept until it succeeds so a
363	  // retry after a failure resends the same Idempotency-Key.
364	  const [pending, setPending] = useState(null);
365	  const [inFlight, setInFlight] = useState(false);
366	  const inFlightRef = useRef(false); // guards double clicks before the re-render disables the button
367	  const [error, setError] = useState(null);
368	  const [result, setResult] = useState(null);
369	
370	  useEffect(() => {
371	    api.courses(token).then(
372	      (list) => {
373	        setCourses(list);
374	        if (list.length) setCourseId(String(list[0].id));
375	      },
376	      setCoursesError,
377	    );
378	  }, [token]);
379	
380	  function chooseCourse(id) {
381	    setCourseId(id);
382	    setConfirming(false);
383	    setPending(null); // a different course is a new submission with a new key
384	    setError(null);
385	  }
386	
387	  async function send(submission) {
388	    if (inFlightRef.current) return;
389	    inFlightRef.current = true;
390	    setInFlight(true);
391	    setError(null);
392	    try {
393	      const res = await api.bulkIssue(token, submission.courseId, submission.key);
394	      setResult(res);
395	      setPending(null);
396	    } catch (e) {
397	      setError(e);
398	    } finally {
399	      inFlightRef.current = false;
400	      setInFlight(false);
401	    }
402	  }
403	
404	  function confirm() {
405	    const submission = { courseId: Number(courseId), key: crypto.randomUUID() };
406	    setPending(submission);
407	    setConfirming(false);
408	    setResult(null);
409	    send(submission);
410	  }
411	
412	  if (coursesError) return <ErrorBox error={coursesError} />;
413	  if (!courses) return <p className="muted">Loading…</p>;
414	  if (!courses.length) return <p className="muted">This tenant has no courses.</p>;
415	
416	  const courseTitle = courses.find((c) => String(c.id) === courseId)?.title;
417	
418	  return (
419	    <section>
420	      <div className="toolbar">
421	        <label>
422	          Course{" "}
423	          <select value={courseId} onChange={(e) => chooseCourse(e.target.value)} disabled={inFlight}>
424	            {courses.map((c) => (
425	              <option key={c.id} value={c.id}>
426	                {c.title}
427	              </option>
428	            ))}
429	          </select>
430	        </label>
431	        {!confirming && !pending && (
432	          <button type="button" onClick={() => setConfirming(true)}>
433	            Issue certificates…
434	          </button>
435	        )}
436	      </div>
437	      {confirming && (
438	        <div className="confirm">
439	          <p>
440	            Issue certificates to every eligible learner in <strong>{courseTitle}</strong>?
441	          </p>
442	          <button type="button" onClick={confirm}>
443	            Confirm issue
444	          </button>
445	          <button type="button" onClick={() => setConfirming(false)}>
446	            Cancel
447	          </button>
448	        </div>
449	      )}
450	      {pending && (
451	        <div className="confirm">
452	          <p className="muted">
453	            Request key <span className="mono">{pending.key}</span>
454	          </p>
455	          <button type="button" onClick={() => send(pending)} disabled={inFlight}>
456	            {inFlight ? "Issuing…" : "Retry"}
457	          </button>
458	          <button type="button" onClick={() => chooseCourse(courseId)} disabled={inFlight}>
459	            Discard
460	          </button>
461	        </div>
462	      )}
463	      <ErrorBox error={error} />
464	      {result && <BulkResult result={result} />}
465	    </section>
466	  );
467	}
468	
469	function BulkResult({ result }) {
470	  const { issued, skipped, failed } = result.summary;
471	  return (
472	    <>
473	      <p>
474	        Operation #{result.operation_id}: <strong>{issued}</strong> issued, <strong>{skipped}</strong>{" "}
475	        skipped, <strong>{failed}</strong> failed.
476	      </p>
477	      <table>
478	        <thead>
479	          <tr>
480	            <th>Learner</th>
481	            <th>Outcome</th>
482	            <th>Reason</th>
483	            <th>Certificate</th>
484	          </tr>
485	        </thead>
486	        <tbody>
487	          {result.results.map((r) => (
488	            <tr key={r.learner_id}>
489	              <td>{r.learner_name}</td>
490	              <td>
491	                <span className={`badge ${r.outcome}`}>{r.outcome}</span>
492	              </td>
493	              <td>{r.reason ?? "—"}</td>
494	              <td>{r.certificate_id ?? "—"}</td>
495	            </tr>
496	          ))}
497	        </tbody>
498	      </table>
499	    </>
500	  );
501	}

