 11	async function request(path, { token, method = "GET", headers = {}, body, signal } = {}) {
 12	  let res;
 13	  try {
 14	    res = await fetch(path, {
 15	      method,
 16	      signal,
 17	      headers: {
 18	        ...(token ? { "X-Actor-Token": token } : {}),
 19	        ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
 20	        ...headers,
 21	      },
 22	      body: body !== undefined ? JSON.stringify(body) : undefined,
 23	    });
 24	  } catch (e) {
 25	    if (e.name === "AbortError") throw e;
 26	    throw new ApiError(0, "network_error", "Network error: the server could not be reached.");
 27	  }
 28	  if (!res.ok) {
 29	    let code = "http_error";
 30	    let message = `Request failed (${res.status}).`;
 31	    try {
 32	      const data = await res.json();
 33	      code = data.error?.code ?? code;
 34	      message = data.error?.message ?? message;
 35	    } catch {
 36	      // non-JSON error body; keep the generic message
 37	    }
 38	    throw new ApiError(res.status, code, message);
 39	  }
 40	  return res;
 41	}
