 45	export const api = {
 46	  actors: () => json(request("/api/actors")),
 47	  me: (token) => json(request("/api/me", { token })),
 48	  courses: (token) => json(request("/api/courses", { token })),
 49	  listCertificates: (token, params, signal) =>
 50	    json(request(`/api/certificates?${new URLSearchParams(params)}`, { token, signal })),
 51	  certificate: (token, id) => json(request(`/api/certificates/${id}`, { token })),
 52	  revoke: (token, id) => json(request(`/api/certificates/${id}/revoke`, { token, method: "POST" })),
 53	  bulkIssue: (token, courseId, key) =>
 54	    json(
 55	      request("/api/bulk-issues", {
 56	        token,
 57	        method: "POST",
 58	        headers: { "Idempotency-Key": key },
 59	        body: { course_id: courseId },
 60	      }),
 61	    ),
 62	  // The export needs the actor header, so a plain <a href> can't fetch it:
 63	  // download via fetch, then hand the blob to the browser as a file.
